"""ES256 签名与规范化 JSON。

ES256 即 ECDSA over P-256 与 SHA-256。签名以 JWS 约定编码：
64 字节裸 R||S 的 base64url（无填充）。cryptography 库签出的是 DER，
这里在 DER 与 R||S 之间做转换。
"""

import base64
import json
import re
from typing import Any, Dict

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import (
    decode_dss_signature,
    encode_dss_signature,
)

__all__ = [
    "InvalidSignature",
    "MalformedSignature",
    "canonicalize",
    "generate_private_key_pem",
    "public_key_pem_from_private",
    "validate_public_key_pem",
    "validate_signature_format",
    "validate_signature_format_strict",
    "sign",
    "verify",
]


class MalformedSignature(ValueError):
    """签名编码格式非法（无法解码或不是 64 字节裸 R||S）。"""


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode(text + padding)


def canonicalize(body: Dict[str, Any]) -> bytes:
    """正文按 key 升序的规范化 JSON 序列化（紧凑、UTF-8 字节）。"""
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def generate_private_key_pem() -> str:
    """生成 P-256 私钥，返回 PKCS8 PEM 字符串。"""
    private_key = ec.generate_private_key(ec.SECP256R1())
    pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return pem.decode("utf-8")


def public_key_pem_from_private(private_pem: str) -> str:
    """从私钥 PEM 导出对应的 SubjectPublicKeyInfo 公钥 PEM。"""
    private_key = serialization.load_pem_private_key(
        private_pem.encode("utf-8"), password=None
    )
    if not isinstance(private_key, ec.EllipticCurvePrivateKey):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    if not isinstance(private_key.curve, ec.SECP256R1):
        raise ValueError("私钥曲线不是 P-256")
    pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return pem.decode("utf-8")


def _load_public_key(public_pem: str) -> ec.EllipticCurvePublicKey:
    try:
        key = serialization.load_pem_public_key(public_pem.encode("utf-8"))
    except (ValueError, TypeError) as exc:
        raise ValueError(f"公钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePublicKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("公钥不是 P-256 椭圆曲线公钥")
    return key


def validate_public_key_pem(public_pem: str) -> None:
    """校验公钥 PEM 可解析且为 ES256 所需的 P-256 公钥，否则抛 ValueError。"""
    _load_public_key(public_pem)


def _load_private_key(private_pem: str) -> ec.EllipticCurvePrivateKey:
    try:
        key = serialization.load_pem_private_key(
            private_pem.encode("utf-8"), password=None
        )
    except (ValueError, TypeError) as exc:
        raise ValueError(f"私钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    return key


def sign(body: Dict[str, Any], private_pem: str) -> str:
    """对规范化正文做 ES256 签名，返回 base64url(R||S)。"""
    private_key = _load_private_key(private_pem)
    der = private_key.sign(
        canonicalize(body), ec.ECDSA(hashes.SHA256())
    )
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return _b64url(raw)


def validate_signature_format(signature_b64: str) -> None:
    """校验签名编码格式：须为可解码的 base64url 且裸 R||S 恰为 64 字节。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    try:
        raw = _b64url_decode(signature_b64)
    except Exception as exc:  # noqa: BLE001 解码异常（含 binascii）均属格式问题
        raise MalformedSignature("签名不是合法的 base64url 编码") from exc
    if len(raw) != 64:
        raise MalformedSignature("签名长度不是 64 字节，非合法 ES256 签名")


# 严格格式：64 字节裸 R||S 的无填充 base64url 恰为 86 个字符
_RAW_RS_B64URL_STRICT_RE = re.compile(r"[A-Za-z0-9_-]{86}")


def validate_signature_format_strict(signature_b64: str) -> None:
    """严格校验签名编码格式：恰为 86 个 base64url 字符（无填充、无字
    母表外字符），解码恰为 64 字节裸 R||S，且无填充 base64url 重编码
    与原文逐字符一致（排除填充与非规范尾位）。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    if not isinstance(signature_b64, str) or not (
        _RAW_RS_B64URL_STRICT_RE.fullmatch(signature_b64)
    ):
        raise MalformedSignature(
            "签名不是 86 字符的无填充 base64url 编码"
        )
    raw = _b64url_decode(signature_b64)
    if len(raw) != 64 or _b64url(raw) != signature_b64:
        raise MalformedSignature(
            "签名不是规范的 64 字节裸 R||S 无填充 base64url 编码"
        )


def verify(body: Dict[str, Any], signature_b64: str, public_pem: str) -> None:
    """校验签名：格式非法抛 MalformedSignature，验签失败抛 InvalidSignature。"""
    validate_signature_format(signature_b64)
    public_key = _load_public_key(public_pem)
    raw = _b64url_decode(signature_b64)
    r = int.from_bytes(raw[:32], "big")
    s = int.from_bytes(raw[32:], "big")
    der = encode_dss_signature(r, s)
    public_key.verify(der, canonicalize(body), ec.ECDSA(hashes.SHA256()))

def _post_trust_credential_status_sync(self, tenant: str) -> None:
    # 外部凭证状态同步。请求/字段非法由 _read_json 与 store 抛
    # ValidationError -> 400；同 updated_at 不同内容由 store 抛
    # ConflictError -> 409。锚点缺失/吊销、签名格式错误、验签
    # 失败均按公开错误协议返回 200 + {"valid":false,"reason":...}
    # （前缀依次为“锚点”/“签名格式错误”/“签名校验失败”）且不写入。
    data = self._read_json()
    result = store.sync_credential_status(tenant, data)
    if not result.get("valid"):
        self._send_invalid(result.get("reason") or "验签失败")
        return
    record = result["record"]
    # 首次同步 201；严格更新或重放 200（重放内容不变）。
    self._send_json(
        result["status_code"],
        {
            "issuer_did": record.issuer_did,
            "credential_id": record.credential_id,
            "status": record.status,
            "reason": record.reason,
            "updated_at": record.updated_at,
            "issuer_key_version": record.issuer_key_version,
        },
    )

def _post_trust_credential_status_sync_batch(
    self, tenant: str
) -> None:
    # 批量外部凭证状态同步：任何失败都返回 HTTP 200。请求体须恰为
    # {"items": [项...]}，数组非空且不超过 100 项；请求体非法
    # （外层缺失、非法 JSON、非对象、字段缺失或多余、items 非数组、
    # 空数组或超过上限）时返回 {"results": [], "reason": "请求..."}。
    # 请求级合法时返回 {"results": [...]}，长度与顺序与输入一致，
    # 逐项复用单项同步规则，失败不短路：字段错误 400、同秒冲突
    # 409、锚点/签名失败 200 均收敛为单项结果（含 http_status 与
    # 非空中文 reason），不影响其余项；成功项首次 201，重放/更早
    # 日 200，严格更新 200 并记审计。显式空 X-Tenant-ID 在此之前
    # 由路由统一判 400；本地（本租户）凭证状态始终不变。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    try:
        ok, reason, results = store.sync_credential_status_batch(
            tenant, data
        )
    except Exception:  # noqa: BLE001 批量同步失败绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 同步过程发生内部错误"}
        )
        return
    if not ok:
        self._send_json(
            200, {"results": [], "reason": reason or "请求不合法"}
        )
        return
    self._send_json(200, {"results": results})

def _post_trust_credential_status_receipt(self, tenant: str) -> None:
    # POST /v1/trust/credential-status/receipt：凭证状态同步签名

def sync_credential_status(
    self,
    tenant_id: str,
    data: Any,
) -> Dict[str, Any]:
    """同步一条外部凭证状态，返回结果字典。

    请求体须恰含 body（JSON 对象）与 signature（非空字符串）；
    body 须恰含 issuer_did、credential_id、status、updated_at、
    issuer_key_version，并可选 reason：
      - issuer_did/credential_id/status/updated_at 为非空字符串；
      - status 仅 active、revoked、unknown、suspended；
      - issuer_key_version 为非布尔正整数；
      - updated_at 为 UTC 秒精度 Z 格式（YYYY-MM-DDTHH:MM:SSZ）；
      - status 为 suspended 时 reason 必填：须为字符串且首尾裁剪后
        为 1..256 个 Unicode 码点，否则抛 ValidationError（消息恰为
        “非空中文原因”，HTTP 400 仅返 {"error":"非空中文原因"}）；
        验签通过后保存裁剪值，重放/冲突判定以裁剪后内容为准；
      - 其余 status 下 reason 提供时须为非空字符串（按原文保存）。
    任何请求/字段非法均抛 ValidationError（HTTP 400）。

    签名覆盖 body 的规范化 JSON，用本租户 (issuer_did,
    issuer_key_version) 的 active 信任锚点公钥验签。锚点缺失/吊销、
    签名格式错误、密码学验签失败均不抛异常、不写入、不记审计，返回
    {"valid": False, "reason": ...}（reason 前缀依次为
    “锚点”/“签名格式错误”/“签名校验失败”）。

    验签通过后按 (issuer_did, credential_id) 双键在本租户内持久化：
      - 首次同步 201；
      - 相同内容（同 updated_at 且 status/version/reason 相同）重放
        200，不替换、不重复审计；
      - updated_at 严格更新才替换（200 并记审计）；更早或相等内容
        时间但内容不同的处理见下；
      - 同 updated_at 但内容不同抛 ConflictError（409），不写入。
    成功变更（首次或严格更新）记 trust.credential.status.synced，
    resource_id 为 issuer_did#credential_id；状态与审计同一次原子写，
    失败回滚。绝不改动本租户既有凭证状态。
    """
    # ---- 请求结构（错误 -> 400）----
    if not isinstance(data, dict):
        raise ValidationError("请求体必须为 JSON 对象")
    if set(data) != {"body", "signature"}:
        missing = [f for f in ("body", "signature") if f not in data]
        if missing:
            raise ValidationError(f"缺少字段: {', '.join(missing)}")
        extra = sorted(set(data) - {"body", "signature"})
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    body = data["body"]
    signature = data["signature"]
    if not isinstance(body, dict):
        raise ValidationError("字段 body 必须为 JSON 对象")
    if not isinstance(signature, str) or not signature:
        raise ValidationError("字段 signature 必须为非空字符串")

    # ---- body 字段（错误 -> 400）----
    required = (
        "issuer_did",
        "credential_id",
        "status",
        "updated_at",
        "issuer_key_version",
    )
    for field in required:
        if field not in body:
            raise ValidationError(f"body 缺少字段: {field}")
    extra = sorted(set(body) - set(required) - {"reason"})
    if extra:
        raise ValidationError(f"body 含多余字段: {', '.join(extra)}")
    issuer_did = body["issuer_did"]
    credential_id = body["credential_id"]
    status = body["status"]
    updated_at = body["updated_at"]
    key_version = body["issuer_key_version"]
    for name, value in (
        ("issuer_did", issuer_did),
        ("credential_id", credential_id),
        ("status", status),
        ("updated_at", updated_at),
    ):
        if not isinstance(value, str) or not value:
            raise ValidationError(
                f"body 字段 {name} 必须为非空字符串"
            )
    if status not in ("active", "revoked", "unknown", "suspended"):
        raise ValidationError(
            "body 字段 status 仅支持 active、revoked、unknown、suspended"
        )
    if not isinstance(key_version, int) or isinstance(
        key_version, bool
    ) or key_version < 1:
        raise ValidationError(
            "body 字段 issuer_key_version 必须为非布尔正整数"
        )
    try:
        incoming_dt = _parse_utc_z(updated_at)
    except (TypeError, ValueError):
        raise ValidationError(
            "body 字段 updated_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    reason: Optional[str] = None
    if status == "suspended":
        # suspended 的 reason 必填：须为字符串且首尾裁剪后为 1..256
        # 个 Unicode 码点，否则单项 400 仅返 {"error":"非空中文原因"}
        # （批量项按序收敛为 valid:false、http_status:400、同一中文
        # reason），均不写入。签名仍覆盖请求提交的原始 body；验签
        # 通过后保存裁剪值，重放/冲突判定也以裁剪后内容为准。
        raw_reason = body.get("reason")
        if not isinstance(raw_reason, str):
            raise ValidationError("非空中文原因")
        trimmed_reason = raw_reason.strip()
        if not 1 <= len(trimmed_reason) <= 256:
            raise ValidationError("非空中文原因")
        reason = trimmed_reason
    elif "reason" in body:
        reason = body["reason"]
        if not isinstance(reason, str) or not reason:
            raise ValidationError("body 字段 reason 必须为非空字符串")

    # ---- 锚点（缺失/吊销 -> 200 valid:false，且不写入）----
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None
            else None
        )
        anchor_row = (
            anchors.get(str(key_version))
            if anchors is not None
            else None
        )
        public_pem = (
            anchor_row.get("public_key", "")
            if anchor_row is not None
            else ""
        )
        anchor_status = (
            anchor_row.get("status", "active")
            if anchor_row is not None
            else None
        )
        anchor_uses = (
            anchor_row.get("uses")
            if anchor_row is not None
            else None
        )
    if anchor_row is None:
        return {
            "valid": False,
            "reason": f"锚点不存在: {issuer_did}#{key_version}",
        }
    if anchor_status == "revoked":
        return {
            "valid": False,
            "reason": f"锚点已吊销: {issuer_did}#{key_version}",
        }
    # 用途白名单：active 锚点无 status 用途时按锚点不可用处理
    if anchor_uses is not None and "status" not in anchor_uses:
        return {
            "valid": False,
            "reason": f"锚点不存在: {issuer_did}#{key_version}",
        }
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return {
            "valid": False,
            "reason": (
                f"锚点公钥不可用: {issuer_did}#{key_version}"
                " 不是合法 P-256 公钥"
            ),
        }

